/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let n, m;
let word;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 2) {
    [n, m] = lines[0].split(" ").map(Number);
    word = lines[1];
  }

  if (n && lines.length === n + 2) {
    lines.shift();
    lines.shift();

    console.log(canFind(lines, n, m, word));

    lines.length = 0;
  }
});

function canFind(matrix, n, m, word) {
  const len = word.length;
  const visited = new Array(n).fill(0).map(() => new Array(m).fill(false));

  const backTracking = (i, j, k) => {
    if (k === len) return true;

    if (
      i < 0 ||
      i >= n ||
      j < 0 ||
      j >= m ||
      visited[i][j] ||
      matrix[i][j] !== word[k]
    )
      return false;

    visited[i][j] = true;

    const newK = k + 1;
    const res =
      backTracking(i - 1, j, newK) ||
      backTracking(i + 1, j, newK) ||
      backTracking(i, j - 1, newK) ||
      backTracking(i, j + 1, newK);

    visited[i][j] = false;
    return res;
  }

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      if (backTracking(i, j, 0)) {
        return `${i + 1} ${j + 1}`;
      }
    }
  }

  return "NO";
}

